<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Clock, InfoFilled, MoonNight, Phone } from '@element-plus/icons-vue'
import { api } from '@/api/client'

interface LateReturn { id:number; returnDate:string; expectedTime:string; reason:string; contact:string; status:string; createdAt:string }
const records=ref<LateReturn[]>([])
const submitting=ref(false)
const form=reactive({returnDate:'2026-09-10',expectedTime:'23:30',reason:'',contact:'18700004831'})
const hasPending=computed(()=>records.value.some(item=>item.status==='待确认'&&item.returnDate===form.returnDate))
async function load(){records.value=await api.get<LateReturn[]>('/api/student/late-returns')}
async function submit(){
  if(form.reason.trim().length<5)return ElMessage.warning('请简要填写晚归原因')
  if(!form.contact.trim())return ElMessage.warning('请填写联系电话')
  submitting.value=true
  try{await api.post('/api/student/late-returns',form);ElMessage.success('登记成功，请注意安全');form.reason='';await load()}
  catch(error){ElMessage.error(error instanceof Error?error.message:'登记失败')}
  finally{submitting.value=false}
}
onMounted(load)
</script>

<template><div><div class="student-page-head"><span>LATE RETURN</span><h1>晚归登记</h1><p>预计超过 23:00 返回宿舍时，请提前登记并保持电话畅通。</p></div><section class="late-grid"><article class="student-card form-card"><header><div><el-icon><MoonNight/></el-icon><h2>填写晚归信息</h2></div><span>当前宿舍：松园1号楼 302</span></header><div class="form-body"><div class="form-row"><label><span>晚归日期</span><input v-model="form.returnDate" type="date"/></label><label><span>预计返回时间</span><input v-model="form.expectedTime" type="time"/></label></div><label><span>晚归原因</span><textarea v-model="form.reason" maxlength="150" placeholder="例如：参加学院活动、实验室项目讨论等"/><small>{{form.reason.length}} / 150</small></label><label><span>联系电话</span><div class="phone-input"><el-icon><Phone/></el-icon><input v-model="form.contact" placeholder="请输入可联系的手机号"/></div></label><div class="safety-tip"><el-icon><InfoFilled/></el-icon><p><strong>安全提醒</strong><span>请尽量结伴返回，途中注意人身和财物安全。如预计时间发生变化，请及时联系宿管老师。</span></p></div><button class="submit" :disabled="submitting||hasPending" @click="submit">{{hasPending?'当天已完成登记':submitting?'正在提交...':'确认登记'}}</button></div></article><aside><article class="student-card rule-card"><header><h2>登记说明</h2></header><ul><li><i><Clock/></i><span><strong>登记时间</strong><small>建议在当日 22:30 前提交</small></span></li><li><i><Phone/></i><span><strong>保持联系</strong><small>宿管可能电话确认返校情况</small></span></li><li><i><MoonNight/></i><span><strong>及时返回</strong><small>返回后请轻声进入宿舍</small></span></li></ul></article><div class="contact-card"><span>紧急联系电话</span><strong>138 0000 1201</strong><small>松园 1 号楼宿管值班室</small></div></aside></section><section class="student-card history"><header><h2>我的登记记录</h2><span>共 {{records.length}} 条</span></header><div v-if="records.length"><article v-for="item in records" :key="item.id"><div class="date-badge"><strong>{{item.returnDate.slice(8)}}</strong><span>{{item.returnDate.slice(5,7)}}月</span></div><div class="record-main"><strong>预计 {{item.expectedTime}} 返回</strong><span>{{item.reason}}</span><small>提交于 {{item.createdAt}}</small></div><b :class="{done:item.status==='已确认',contacted:item.status==='已联系'}">{{item.status}}</b></article></div><div v-else class="empty">暂无晚归登记记录</div></section></div></template>

